import heapq

def match(orders):
    trades = []
    seq_counter = 0

    # order info storage: id -> dict with side, price, remaining, active, seq
    book = {}

    # heaps
    sell_heap = []  # entries: (price, seq, id)
    buy_heap = []   # entries: (-price, seq, id)

    def push_resting(order_id):
        info = book[order_id]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], info['seq'], order_id))
        else:
            heapq.heappush(sell_heap, (info['price'], info['seq'], order_id))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                info = book[oid]
                if info['active'] and info['remaining'] > 0:
                    info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            resting_id = top[2]
            resting_info = book.get(resting_id)
            if resting_info is None or (not resting_info['active']) or resting_info['remaining'] <= 0:
                heapq.heappop(opp_heap)
                continue

            resting_price = resting_info['price']

            if typ == 'market':
                price_ok = True
            elif side == 'buy':
                price_ok = resting_price <= price
            else:
                price_ok = resting_price >= price

            if not price_ok:
                break

            heapq.heappop(opp_heap)

            trade_qty = min(remaining, resting_info['remaining'])

            if side == 'buy':
                buy_id = oid
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining -= trade_qty
            resting_info['remaining'] -= trade_qty

            if resting_info['remaining'] > 0:
                heapq.heappush(opp_heap, (top[0], top[1], resting_id))
            else:
                resting_info['active'] = False

        if typ == 'limit' and remaining > 0:
            book[oid] = {
                'side': side,
                'price': price,
                'remaining': remaining,
                'active': True,
                'seq': seq_counter
            }
            seq_counter += 1
            push_resting(oid)
        else:
            if oid not in book:
                book[oid] = {
                    'side': side,
                    'price': price if price is not None else 0,
                    'remaining': 0,
                    'active': False,
                    'seq': seq_counter
                }
                seq_counter += 1

        seq_counter += 0  # no-op, seq already incremented where needed

    return trades

